  const edge = e.target.dataset.edge || 'move', x0 = e.clientX, o = { ...c }, buf = AE.buffers.get(c.asset), srcLen = buf ? buf.duration : (assetOf(c.asset)?.duration || c.offset + c.length); const targets = snapTargets(c.id); let moved = false; const before = snap(); el.setPointerCapture(e.pointerId); el.style.cursor = edge === 'move' ? 'grabbing' : 'ew-resize';
